 import { MeshStandardNodeMaterial, MeshBasicNodeMaterial, PlaneGeometry, BoxGeometry, Group, Mesh, PointLight, DirectionalLight } from 'three/webgpu';
import { uv, smoothstep, mix, color as nColor } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry: PlGeo, BoxGeometry: BxGeo, PointLight: PtL, DirectionalLight: DirL } = THREE;

  const palette = {
    bg: '#0b0b10',
    surface: '#14141a',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38'
  };

  const root = new Group();
  root.position.set(0, 0, 0);

  const column = new Group();
  column.position.set(0.9, 0, 0);
  root.add(column);

  // Backdrop gradient stage
  const backdropGeo = new PlGeo(7.2, 6);
  const backdropMat = new MeshBasicNodeMaterial({
    colorNode: mix(nColor(palette.bg), nColor(palette.surface), smoothstep(0, 1, uv().y))
  });
  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, -0.25, -2.5);
  root.add(backdrop);

  // Local lighting
  const key = new DirL(new THREE.Color(palette.paper), 1.1);
  key.position.set(4, 5, 6);
  root.add(key);

  const rim = new PtL(new THREE.Color(palette.accent), 0.9);
  rim.position.set(-2.2, 0.2, 2.4);
  root.add(rim);

  // Text content bridge
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find(i => i.role === 'headline') ?? { text: 'Inside the atelier', typography: { fontSize: 68 } };
  const captionItems = items.filter(i => i.role === 'caption');

  const captionSource = [
    'DIAL ROOM',
    'ESCAPEMENT BENCH',
    'CNC HALL',
    'FINISHING LAB',
    'ARCHIVE VAULT',
    'ASSEMBLY LINE ONE'
  ];

  const headline = ctx.fontAtlas.createText(headlineItem.text, {
    fontSize: 0.62,
    color: palette.paper,
    align: 'left'
  });
  headline.position.set(-1.6, 1.9, 0.12);
  root.add(headline);

  const captions = [];
  for (let i = 0; i < 6; i++) {
    const item = captionItems[i] ?? { text: captionSource[i] };
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: 0.13,
      color: palette.paper,
      align: 'right',
      letterSpacingPx: 2
    });
    txt.position.set(-1.6, 0, 0.14);
    txt.visible = false;
    txt.traverse(m => {
      if (m.material) {
        m.material.transparent = true;
        m.material.opacity = 0;
      }
    });
    root.add(txt);
    captions.push({ obj: txt, state: { opacity: 0 } });
  }

  // Plate construction
  const W = 1.9;
  const H = 1.2;
  const PITCH = 1.5;
  const LOOP = 9.0;

  const frameMat = new MeshStandardNodeMaterial({
    color: new THREE.Color(palette.ink),
    roughness: 0.5,
    metalness: 0.5,
    clearcoat: 0.1
  });

  const accentMat = new MeshStandardNodeMaterial({
    color: new THREE.Color(palette.accent),
    emissive: new THREE.Color(palette.accent),
    emissiveIntensity: 1.4,
    roughness: 0.5,
    metalness: 0.1
  });

  const tints = [
    new THREE.Color('#ffffff'),
    new THREE.Color('#f2e8dc'),
    new THREE.Color('#e8ecf2'),
    new THREE.Color('#d6cfc7'),
    new THREE.Color('#c9c9c3'),
    new THREE.Color('#e2ded8')
  ];

  const plates = [];
  for (let i = 0; i < 6; i++) {
    const plate = new Group();

    const frame = new THREE.Mesh(new BxGeo(W + 0.06, H + 0.06, 0.04), frameMat);
    plate.add(frame);

    const photoMat = new MeshStandardNodeMaterial({
      color: tints[i],
      roughness: 0.6,
      metalness: 0.1,
      clearcoat: 0.1
    });

    const photo = new THREE.Mesh(new PlGeo(W, H), photoMat);
    photo.position.z = 0.025;
    plate.add(photo);

    const strip = new THREE.Mesh(new BxGeo(0.03, H + 0.06, 0.05), accentMat.clone());
    strip.position.set(-(W + 0.06) / 2 - 0.015, 0, 0.03);
    strip.visible = false;
    plate.add(strip);

    column.add(plate);
    plates.push({ group: plate, photoMat, strip });
  }

  // Load the single base photograph and derive 6 distinct crops/variants
  ctx.textureLoader.loadTexture(config.imageUrl).then(tex => {
    tex.colorSpace = THREE.SRGBColorSpace || 'srgb';
    tex.wrapS = THREE.RepeatWrapping;
    tex.wrapT = THREE.RepeatWrapping;

    const crops = [
      { repeat: [0.5, 0.5], offset: [0.0, 0.0] },
      { repeat: [0.5, 0.5], offset: [0.5, 0.0] },
      { repeat: [0.5, 0.5], offset: [0.0, 0.5] },
      { repeat: [0.5, 0.5], offset: [0.5, 0.5] },
      { repeat: [0.5, 0.5], offset: [0.25, 0.25] },
      { repeat: [0.5, 0.5], offset: [0.0, 0.25] }
    ];

    plates.forEach((p, idx) => {
      const crop = crops[idx];
      const cloned = tex.clone();
      cloned.repeat.set(crop.repeat[0], crop.repeat[1]);
      cloned.offset.set(crop.offset[0], crop.offset[1]);
      cloned.needsUpdate = true;
      p.photoMat.map = cloned;
      p.photoMat.needsUpdate = true;
    });
  }).catch(() => {});

  // Scroll state + loop layout
  let targetY = 0;
  let currentY = 0;
  let velocity = 0;
  let focusIndex = -1;
  const DAMP = 0.12;

  function setCaptionOpacity(capObj, target, dur = 0.35) {
    gsap.killTweensOf(capObj.state);
    gsap.to(capObj.state, {
      opacity: target,
      duration: dur,
      ease: 'power2.out',
      onUpdate: () => {
        capObj.obj.traverse(m => {
          if (m.isMesh && m.material) m.material.opacity = capObj.state.opacity;
        });
      }
    });
  }

  function focusPlate(idx, focusY) {
    if (focusIndex === idx) {
      captions[idx].obj.position.y = focusY - 0.42;
      return;
    }
    focusIndex = idx;

    for (let i = 0; i < plates.length; i++) {
      const targetScale = i === idx ? 1.06 : 1.0;
      gsap.killTweensOf(plates[i].group.scale);
      gsap.to(plates[i].group.scale, {
        x: targetScale,
        y: targetScale,
        z: targetScale,
        duration: 0.35,
        ease: 'cubic-bezier(0.215,0.61,0.355,1)'
      });
      plates[i].strip.visible = (i === idx);
    }

    for (let i = 0; i < captions.length; i++) {
      captions[i].obj.visible = (i === idx);
      setCaptionOpacity(captions[i], i === idx ? 1 : 0, 0.35);
    }
  }

  function layout() {
    velocity += (targetY - currentY) * DAMP;
    velocity *= (1 - DAMP);
    currentY += velocity;

    const loop = currentY % LOOP;
    let nearestIdx = -1;
    let nearestDist = Infinity;
    let nearestY = 0;

    plates.forEach((p, i) => {
      let y = i * PITCH - loop;
      if (y > LOOP * 0.5) y -= LOOP;
      else if (y < -LOOP * 0.5) y += LOOP;

      p.group.position.y = y;

      const dist = Math.abs(y);
      if (dist < nearestDist) {
        nearestDist = dist;
        nearestIdx = i;
        nearestY = y;
      }
    });

    if (nearestIdx !== -1) {
      focusPlate(nearestIdx, nearestY);
    }
  }

  function tick() {
    layout();
  }
  gsap.ticker.add(tick);

  root.userData.handlers = root.userData.handlers || {};
  root.userData.handlers.scroll = (payload) => {
    const delta = payload?.delta ?? (payload?.progress !== undefined ? payload.progress * 1.5 : 0);
    targetY += delta * 1.5;
  };

  // Apply cinematic primitives
  const primitiveReturns = [];
  const primitives = config.cinematicPrimitives || [];
  for (const p of primitives) {
    if (ctx.primitives && ctx.primitives[p.name]) {
      primitiveReturns.push(ctx.primitives[p.name](root, p.params ?? {}));
    }
  }

  // Entrance
  const entrance = gsap.timeline();
  root.scale.set(0.98, 0.98, 0.98);
  entrance.to(root.scale, { x: 1, y: 1, z: 1, duration: 0.75, ease: 'power3.out' });
  entrance.from(backdrop.material, { opacity: 0, duration: 0.7, ease: 'power2.out' }, 0);

  root.userData.cleanup = () => {
    entrance.kill();
    for (const p of primitiveReturns) {
      if (p && typeof p.cleanup === 'function') p.cleanup();
    }
    gsap.ticker.remove(tick);
    gsap.globalTimeline.clear();

    for (const cap of captions) gsap.killTweensOf(cap.state);

    // dispose plates
    for (const p of plates) {
      gsap.killTweensOf(p.group.scale);
      p.group.traverse(o => {
        if (o.geometry) o.geometry.dispose();
        if (o.material) {
          if (o.material.map) o.material.map.dispose();
          o.material.dispose();
        }
      });
    }

    frameMat.dispose();
    accentMat.dispose();

    headline.traverse(o => {
      if (o.geometry) o.geometry.dispose();
      if (o.material) o.material.dispose();
    });
    for (const cap of captions) {
      cap.obj.traverse(o => {
        if (o.geometry) o.geometry.dispose();
        if (o.material) o.material.dispose();
      });
    }

    backdropGeo.dispose();
    backdropMat.dispose();

    root.remove(column);
    root.remove(backdrop);
    root.remove(key);
    root.remove(rim);
    root.remove(headline);
    for (const cap of captions) root.remove(cap.obj);
  };

  return root;
}
